//! 🔗️ Actual qualified member-read custody issues its immutable typed source under the original caller grant.
use super::{ChildEditorRead,ChildEditorCapability};
use crate::child_view::child_editor::source::ChildEditorStamp;
use semio_framework_io_ports::ChildAdmissionQualificationV1;
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,retained_clone::{RetainedCloneSource,RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits},retirement::{RetireOwned,controlled::ControlledRetirement}};
use store::os_store::snapshot_read::{SnapshotRead,ErasedSnapshotRead};
type Issued<S:RetireOwned+Sync>=RetainedCloneSource<S,SnapshotRead<S>>;
#[derive(semio_framework_value::RetireOwned)]
pub struct ChildReadSourceCustody<S:RetireOwned+Sync,Q:RetireOwned+Sync+Copy+Eq+ChildAdmissionQualificationV1>{original:Option<SnapshotRead<S>>,issued:Option<Issued<S>>,stamp:Option<Q>,closing:bool}
pub type ChildEditorSourceCustody<S:RetireOwned+Sync>=ChildReadSourceCustody<S,ChildEditorStamp>;
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl<S:RetireOwned+Sync,Q:RetireOwned+Sync+Copy+Eq+ChildAdmissionQualificationV1> ChildReadSourceCustody<S,Q>{
 const HEADER:usize=2*std::mem::size_of::<Self>();
 pub fn new()->Self{Self{original:None,issued:None,stamp:None,closing:false}}
 pub fn next_admit_demand(&self)->Result<RetirementDemand,ValueError>{if self.closing{return Err(refusal("child original read custody is closing"))}if self.issued.is_some(){return Ok(RetirementDemand{copy_bytes:Self::HEADER,depth:1,..Default::default()})}let d=if self.original.is_some(){let birth=Issued::<S>::borrowed_constructor_demand::<SnapshotRead<S>>();RetirementDemand{copy_bytes:Issued::<S>::borrowed_constructor_copy_bytes::<SnapshotRead<S>>(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()}}else{ErasedSnapshotRead::prepared_read_demands()};Ok(RetirementDemand{copy_bytes:d.copy_bytes.checked_add(Self::HEADER).ok_or_else(||refusal("child source custody copy extent overflow"))?,depth:d.depth.checked_add(1).ok_or_else(||refusal("child source custody depth overflow"))?,..d})}
 pub fn source(&self)->Result<RetainedCloneRef<'_,S>,ValueError>{if self.closing{return Err(refusal("child original read custody is closing"))}self.issued.as_ref().ok_or_else(||refusal("child original source is not issued"))?.try_borrow()}
 pub fn opaque_source(&self)->Result<semio_framework_io_ports::ChildAdmissionSource<'_>,ValueError>{Ok(semio_framework_io_ports::erase_child_admission_source(self.source()?,0x4348494c))}
 pub fn stamp(&self)->Option<&Q>{self.stamp.as_ref()}
 pub fn ready(&self)->bool{self.issued.is_some()&&!self.closing}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn into_retirement(self)->Result<ControlledRetirement<Self>,(ValueError,Self)>{ControlledRetirement::new(self)}
}
impl<S:RetireOwned+Sync,Q:RetireOwned+Sync+Copy+Eq+ChildAdmissionQualificationV1> Default for ChildReadSourceCustody<S,Q>{fn default()->Self{Self::new()}}
impl<S:RetireOwned+Sync> ChildEditorRead<'_,S>{
 pub(crate) fn admit_qualified_source<Q:RetireOwned+Sync+Copy+Eq+ChildAdmissionQualificationV1>(&self,capability_identity:usize,stamp:&Q,owner:&mut ChildReadSourceCustody<S,Q>,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let demand=owner.next_admit_demand()?;if !retained_clone_grant_admits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}let qualification=stamp.child_admission_stamp();let matches=qualification.parent_identity==self.parent_identity&&qualification.child_identity==&self.entry.snapshot as*const _ as usize&&qualification.capability_identity==capability_identity&&qualification.parent_revision==*self.parent_revision&&qualification.child_revision==self.entry.revision;if !matches||owner.stamp.as_ref().is_some_and(|prior|*prior!=*stamp){return Err(refusal("qualified child original read or source changed").with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:ChildReadSourceCustody::<S,Q>::HEADER,..Default::default()}))}if owner.issued.is_some(){return Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))}if owner.original.is_none(){let original=self.entry.snapshot.try_duplicate().map_err(|error|{let mut p=error.retained_progress();p.copied_items=p.copied_items.max(1);p.copied_bytes+=ChildReadSourceCustody::<S,Q>::HEADER;error.with_retained_progress(p)})?;let typed=original.try_into_typed::<S>().unwrap_or_else(|_|unreachable!("immutable original was admitted by this typed member loan"));owner.original=Some(typed);owner.stamp=Some(*stamp);return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))}let metadata=ChildReadSourceCustody::<S,Q>::HEADER;let child=RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-metadata,maximum_depth:grant.maximum_depth-1,..grant};let original=owner.original.take().unwrap();match original.admit_retained_clone_source(child){Ok((issued,mut p))=>{owner.issued=Some(issued);p.copied_bytes+=metadata;Ok(RetainedCloneStep::Complete(p))},Err((error,original))=>{owner.original=Some(original);let mut p=error.retained_progress();p.copied_bytes+=metadata;p.copied_items=p.copied_items.max(1);Err(error.with_retained_progress(p))}}}
 pub fn admit_original_source(&self,capability:&'static ChildEditorCapability,stamp:&ChildEditorStamp,owner:&mut ChildEditorSourceCustody<S>,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.admit_qualified_source(capability as*const _ as usize,stamp,owner,grant)}
}
